  "sutta_refs": "සූ. 42. වග්‌ගෙ ඝොසාඝොසානං තතියපඨමා",
  "similar_words": "",
  "notes": [
   "සූත්‍රාර්ථය: සරම්හා පරභූතානං, ස්වරයා කෙරෙන් පර වූ; වග්ගෙ, වර්ගයෙහි; ඝොසාඝොසානං බ්‍යඤ්ජනානං, ඝෝෂ අඝෝෂ ව්‍යඤ්ජනයන්ට; යථාක්කමං, පිළිවෙළින්; වග්ගෙ තතියපඨමක්ඛරා, වර්ගයෙහි තෘතීය ප්‍රථමාක්ෂරයෝ; ඨානෙ, යුක්ත ස්ථානයෙහි; ද්වෙභාවං ගච්ඡන්ති, ද්විත්ව භාවයට පැමිණෙත්."
  ],
