  "group_key": "බ්‍යඤ්‌ජන සන්ධි · 46. තබ්‌බිපරීතූපපදෙ බ්‍යඤ්‌ජනෙ ච",
  "hide_declension": true,
  "khanda_badge": "සන්ධිකණ්ඩ",
  "meaning": "බ්‍යඤ්‌ජන සන්ධි — 46. තබ්‌බිපරීතූපපදෙ බ්‍යඤ්‌ජනෙ ච සූත්‍රයෙන් සිද්ධ වන රූපය",
  "sutta_refs": "සූ. 46. තබ්‌බිපරීතූපපදෙ බ්‍යඤ්‌ජනෙ ච",
  "similar_words": "",
  "notes": [
   "සූත්‍රාර්ථය: බ්‍යඤ්ජනෙ පරෙ, ව්‍යඤ්ජනයා පරකල්හි; උපපදෙ තිට්ඨමානස්ස අවසද්දස්ස ඨානෙ, උපපදස්ථානයෙහි සිටිනා වූ අවශබ්දයාගේ ස්ථානයෙහි; තස්ස ඔකාරස්ස විපරීතො, ඒ ඕකාරයා සම්බන්ධී විපරීතයෙක් වූ; උකාරො ච, උකාරයෙක් ද; හොති, වේ."
  ],
